{"file_path":"src/index.js","content":"export class TableError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

const ZERO_WIDTH_SET = new Set([0x200b, 0x200c, 0x200d, 0xfeff]);

const WIDE_RANGES = [
  [0x1100, 0x115f],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe10, 0xfe19],
  [0xfe30, 0xfe6f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f300, 0x1f64f],
  [0x1f900, 0x1f9ff],
  [0x20000, 0x2fffd],
  [0x30000, 0x3fffd],
];

function isInRange(cp, [lo, hi]) {
  return cp >= lo && cp <= hi;
}

function codePointWidth(cp) {
  if (cp < 0x20) return 0;
  if (cp === 0x7f) return 0;
  if (ZERO_WIDTH_SET.has(cp)) return 0;
  if (cp >= 0x300 && cp <= 0x36f) return 0;
  for (const range of WIDE_RANGES) {
    if (isInRange(cp, range)) return 2;
  }
  return 1;
}

function toCodePoints(text) {
  return Array.from(text);
}

export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  let width = 0;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    width += codePointWidth(cp);
  }
  return width;
}

function checkWidth(width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }
}

function breakWord(word, width) {
  const chars = toCodePoints(word);
  const chunks = [];
  let curChars = [];
  let curWidth = 0;
  for (const ch of chars) {
    const cp = ch.codePointAt(0);
    const w = codePointWidth(cp);
    if (w > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
    }
    if (curWidth + w > width) {
      chunks.push(curChars.join(''));
      curChars = [ch];
      curWidth = w;
    } else {
      curChars.push(ch);
      curWidth += w;
    }
  }
  if (curChars.length > 0) {
    chunks.push(curChars.join(''));
  }
  return chunks;
}

function wrapPiece(piece, width) {
  const trimmed = piece.replace(/^ +| +$/g, '');
  if (trimmed === '') {
    return [''];
  }
  const words = trimmed.split(/ +/);

  const segments = [];
  for (const word of words) {
    const wwidth = stringWidth(word);
    if (wwidth <= width) {
      segments.push({ text: word, forceNewLine: false });
    } else {
      const chunks = breakWord(word, width);
      chunks.forEach((chunk, idx) => {
        segments.push({ text: chunk, forceNewLine: idx > 0 });
      });
    }
  }

  const lines = [];
  let current = '';
  let currentWidth = 0;
  for (const seg of segments) {
    const segWidth = stringWidth(seg.text);
    if (current === '') {
      current = seg.text;
      currentWidth = segWidth;
    } else if (seg.forceNewLine) {
      lines.push(current);
      current = seg.text;
      currentWidth = segWidth;
    } else if (currentWidth + 1 + segWidth <= width) {
      current += ' ' + seg.text;
      currentWidth += 1 + segWidth;
    } else {
      lines.push(current);
      current = seg.text;
      currentWidth = segWidth;
    }
  }
  lines.push(current);
  return lines;
}

export function wrapCell(text, width) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  checkWidth(width);
  const pieces = text.split('\n');
  const result = [];
  for (const piece of pieces) {
    result.push(...wrapPiece(piece, width));
  }
  return result;
}

export function padCell(text, width, align = 'left') {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  checkWidth(width);
  if (align !== 'left' && align !== 'right' && align !== 'center') {
    throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
  }
  const textWidth = stringWidth(text);
  if (textWidth > width) {
    throw new TableError('CELL_TOO_WIDE', 'content is wider than the column');
  }
  const pad = width - textWidth;
  if (align === 'left') {
    return text + ' '.repeat(pad);
  }
  if (align === 'right') {
    return ' '.repeat(pad) + text;
  }
  const leftPad = Math.floor(pad / 2);
  const rightPad = pad - leftPad;
  return ' '.repeat(leftPad) + text + ' '.repeat(rightPad);
}

export function formatTable(rows, options) {
  if (typeof options !== 'object' || options === null) {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }

  const widths = options.widths;
  if (
    !Array.isArray(widths) ||
    widths.length === 0 ||
    !widths.every((w) => Number.isInteger(w) && w >= 1)
  ) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }

  let align;
  if (options.align !== undefined) {
    if (!Array.isArray(options.align) || options.align.length !== widths.length) {
      throw new TableError('BAD_ALIGN', `align must have ${widths.length} entries`);
    }
    for (const a of options.align) {
      if (a !== 'left' && a !== 'right' && a !== 'center') {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${a}`);
      }
    }
    align = options.align;
  } else {
    align = widths.map(() => 'left');
  }

  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    const cellCount = Array.isArray(row) ? row.length : 0;
    if (cellCount !== widths.length) {
      throw new TableError(
        'BAD_ROW_LENGTH',
        `row ${i} has ${cellCount} cells, expected ${widths.length}`,
      );
    }
    for (let j = 0; j < row.length; j += 1) {
      if (typeof row[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }

  if (rows.length === 0) {
    return '';
  }

  const outputLines = [];
  const header = Boolean(options.header);

  rows.forEach((row, rowIndex) => {
    const wrappedCells = row.map((cell, j) => wrapCell(cell, widths[j]));
    const height = Math.max(...wrappedCells.map((lines) => lines.length));
    for (let lineIndex = 0; lineIndex < height; lineIndex += 1) {
      const parts = wrappedCells.map((lines, j) => {
        const lineText = lineIndex < lines.length ? lines[lineIndex] : '';
        return padCell(lineText, widths[j], align[j]);
      });
      outputLines.push(parts.join(' | '));
    }
    if (header && rowIndex === 0) {
      outputLines.push(widths.map((w) => '-'.repeat(w)).join('-+-'));
    }
  });

  return outputLines.join('\n');
}
